23	// DMI register addresses from RISC-V Debug Spec 1.0.
24	constexpr uint8_t kDmcontrol  = 0x10;
25	constexpr uint8_t kDmstatus   = 0x11;
26	constexpr uint8_t kAbstractcs = 0x16;
27	constexpr uint8_t kCommand    = 0x17;
28	constexpr uint8_t kData0      = 0x04;
29	constexpr uint8_t kData1      = 0x05;
30	
31	// CSR numbers from Debug Spec.
32	constexpr uint16_t kCsrDpc  = 0x7B1;
33	constexpr uint16_t kCsrDcsr = 0x7B0;
34	
35	struct DmiOp
36	{
37	  enum class Kind
38	  {
39	    Write,
40	    Read,
41	  };
42	  Kind kind;
43	  uint8_t reg;
44	  uint32_t value;  // for writes only
45	};
46	
47	struct RecordingBus final : hybrid::DmiBus
48	{
49	  std::vector<DmiOp> ops;
50	
51	  // Test-controlled response values for reads.
52	  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
53	  uint32_t abstractcs_value = 0;     // fallback when queue is empty
54	  std::deque<uint32_t> abstractcs_queue; // queued reads drain first
55	
56	  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
57	  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
58	  // fallback). Models real hardware and -- unlike positional queueing -- is
59	  // robust to however many unrelated abstract ops precede the targeted write.
60	  std::optional<uint16_t> fail_csr_write;
61	
62	  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
63	  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
64	  // re-arms to false after firing - tests can flip it back on to fail a
65	  // later PB exec.
66	  bool fail_next_pb_exec = false;
67	
68	  // Mini register file: abstract write-COMMANDs latch the staged DATA0/DATA1
69	  // into regfile[regno]; abstract read-COMMANDs load it back so read-modify-
70	  // write-verify sequences observe their own writes. Regnos in warl_ignore
71	  // model WARL fields the hart pins (the write is recorded but discarded),
72	  // e.g. dcsr.prv on a core without S/U modes.
73	  std::unordered_map<uint16_t, uint64_t> regfile;
74	  std::set<uint16_t> warl_ignore;
75	
76	  void write(uint8_t reg, uint32_t value) override
77	  {
78	    ops.push_back({DmiOp::Kind::Write, reg, value});
79	    if (reg == kData0) staged_data0_ = value;
80	    if (reg == kData1) staged_data1_ = value;
81	    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
82	      cmderr_sticky_ = false;  // W1C clear
83	    if (reg == kCommand && fail_csr_write) {
84	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
85	      const bool is_write = ((value >> 16) & 1u) != 0u;
86	      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
87	        cmderr_sticky_ = true;
88	    }
89	    if (reg == kCommand && value != hybrid::kExecProgbufCmd) {
90	      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
91	      const bool is_write = ((value >> 16) & 1u) != 0u;
92	      if (is_write) {
93	        if (!warl_ignore.count(regno))
94	          regfile[regno] = (uint64_t{staged_data1_} << 32) | staged_data0_;
95	      } else {
96	        const auto it = regfile.find(regno);
97	        const uint64_t v = (it == regfile.end()) ? 0u : it->second;
98	        pending_data0_ = static_cast<uint32_t>(v);
99	        pending_data1_ = static_cast<uint32_t>(v >> 32);
100	      }
101	    }
102	    if (reg == kCommand && value == hybrid::kExecProgbufCmd
103	        && fail_next_pb_exec) {
104	      cmderr_sticky_ = true;
105	      fail_next_pb_exec = false;
106	    }
107	  }
108	
109	  auto read(uint8_t reg) -> uint32_t override
110	  {
111	    ops.push_back({DmiOp::Kind::Read, reg, 0});
112	    if (reg == kDmstatus) return dmstatus_value;
113	    if (reg == kData0)   return pending_data0_;
114	    if (reg == kData1)   return pending_data1_;
115	    if (reg == kAbstractcs) {
116	      if (cmderr_sticky_) return kCmderrMask;
117	      if (!abstractcs_queue.empty()) {
118	        auto v = abstractcs_queue.front();
119	        abstractcs_queue.pop_front();
120	        return v;
121	      }
122	      return abstractcs_value;
123	    }
124	    return 0;
125	  }
126	
127	private:
128	  static constexpr uint32_t kCmderrMask = 0x7u << 8;
129	  bool cmderr_sticky_ = false;
130	  uint32_t staged_data0_  = 0;
131	  uint32_t staged_data1_  = 0;
132	  uint32_t pending_data0_ = 0;
133	  uint32_t pending_data1_ = 0;
134	};
