TEST_CASE("resume with HYBRID_FLAG_V: V CSR abstract writes precede GPR writes")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_V;
  s.vstart = 1;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // x5/x6 are written as scratch for vsetvl inside the V block, so look for
  // x1 specifically -- it is always the first register in the GPR restore loop.
  std::optional<std::size_t> vstart_cmd_idx;
  std::optional<std::size_t> x1_restore_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008))
      vstart_cmd_idx = i;
    if (!x1_restore_cmd_idx && regno == hybrid::regno_gpr(1))
      x1_restore_cmd_idx = i;
  }
  REQUIRE(vstart_cmd_idx.has_value());
  REQUIRE(x1_restore_cmd_idx.has_value());
  CHECK(*vstart_cmd_idx < *x1_restore_cmd_idx);
}

TEST_CASE("resume with HYBRID_FLAG_V: PB fallback when abstract vstart write fails")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_V;
  s.vstart = 42;
  // The abstract write to vstart raises cmderr -> driver must fall back to a
  // Program Buffer csrrw. Keyed to the CSR, not a positional read count, so it
  // survives the V-data reload sweep's leading abstract ops.
  bus.fail_csr_write = 0x008;  // vstart

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // csrrw x0, vstart(0x008), x5 -- stage value in t0(x5), write to vstart via PB
  const uint32_t expected_pb0 = hybrid::encode_csrrw(0, 0x008, 5);
  bool found_pb0 = false;
  bool found_exec = false;
  for (const auto& op : bus.ops) {
    if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
        && op.value == expected_pb0)
      found_pb0 = true;
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && op.value == hybrid::kExecProgbufCmd)
      found_exec = true;
  }
  CHECK(found_pb0);
  CHECK(found_exec);
}

TEST_CASE("resume with HYBRID_FLAG_V: vsetvl PB fires with vl in x5, vtype in x6")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_V;
  s.vl    = 16;
  s.vtype = 0xC1;  // LMUL=1, SEW=64

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Expect: write x5=vl, write x6=vtype, then exec vsetvl x0,x5,x6 in PB.
  const uint32_t expected_vsetvl = hybrid::encode_vsetvl(0, 5, 6);
  bool found_x5_vl    = false;
  bool found_x6_vtype = false;
  bool found_vsetvl   = false;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
      const uint16_t regno = static_cast<uint16_t>(op.value & 0xFFFFu);
      if (regno == hybrid::regno_gpr(5) && i >= 2) {
        const auto& d0 = bus.ops[i - 2];
        const auto& d1 = bus.ops[i - 1];
        if (d0.reg == kData0 && d0.value == uint32_t(s.vl & 0xFFFFFFFFu) &&
            d1.reg == kData1 && d1.value == uint32_t(s.vl >> 32))
          found_x5_vl = true;
      }
      if (regno == hybrid::regno_gpr(6) && i >= 2) {
        const auto& d0 = bus.ops[i - 2];
        const auto& d1 = bus.ops[i - 1];
        if (d0.reg == kData0 && d0.value == uint32_t(s.vtype & 0xFFFFFFFFu) &&
            d1.reg == kData1 && d1.value == uint32_t(s.vtype >> 32))
          found_x6_vtype = true;
      }
    }
    if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
        && op.value == expected_vsetvl)
      found_vsetvl = true;
  }
  CHECK(found_x5_vl);
  CHECK(found_x6_vtype);
  CHECK(found_vsetvl);
}

TEST_CASE("resume with HYBRID_FLAG_V: vsetvl executes before vstart write")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_V;
  s.vstart  = 3;
  s.vl      = 8;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const uint32_t expected_vsetvl = hybrid::encode_vsetvl(0, 5, 6);
  std::optional<std::size_t> vsetvl_pb_idx;
  std::optional<std::size_t> vstart_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (!vsetvl_pb_idx && op.kind == DmiOp::Kind::Write
        && op.reg == hybrid::kProgbuf0 && op.value == expected_vsetvl)
      vsetvl_pb_idx = i;
    if (!vstart_cmd_idx && op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x008))
      vstart_cmd_idx = i;
  }
  REQUIRE(vsetvl_pb_idx.has_value());
  REQUIRE(vstart_cmd_idx.has_value());
  CHECK(*vsetvl_pb_idx < *vstart_cmd_idx);
}

TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
          "before the architectural V-CSR restore and counter restore")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_V;
  s.vlenb  = 64;
  s.vl     = 16;
  s.vtype  = 0xC1;   // differs from the sweep's e8/m1 vtype (0xC0)
  s.vstart = 7;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // (a) every v0..v31 is reloaded via a vle8.v executed in the Program Buffer.
  std::vector<int> missing;
  std::optional<std::size_t> first_vle_idx, last_vle_idx;
  for (uint16_t v = 0; v < 32; ++v) {
    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(v), 7);
    std::optional<std::size_t> at;
    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
      const auto& op = bus.ops[i];
      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
          && op.value == want) { at = i; break; }
    }
    if (!at) { missing.push_back(v); continue; }
    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
  }
  CHECK(missing.empty());
  REQUIRE(first_vle_idx.has_value());
  REQUIRE(last_vle_idx.has_value());

  // (b) the per-register scratch GPA is staged in x7 (base pointer) for the
  //     first and last register.
  auto x7_gpa_staged = [&](uint64_t gpa) {
    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
      const auto& op = bus.ops[i];
      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
          && ((op.value >> 16) & 1u)) {
        const auto& d0 = bus.ops[i - 2];
        const auto& d1 = bus.ops[i - 1];
        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
          return true;
      }
    }
    return false;
  };
  CHECK(x7_gpa_staged(hybrid::kVScratchGpa));
  CHECK(x7_gpa_staged(hybrid::kVScratchGpa + 31ull * HYBRID_VLEN_BYTES_MAX));

  // (c)/(d) the sweep runs before the architectural vstart restore (whose
  //     vsetvl would otherwise be clobbered) and before the mcycle restore
  //     (so the vle8.v insns cannot pollute the resumed counters).
  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008)) vstart_cmd_idx = i;
    if (!mcycle_cmd_idx && regno == hybrid::regno_csr(0xB00)) mcycle_cmd_idx = i;
  }
  REQUIRE(vstart_cmd_idx.has_value());
  REQUIRE(mcycle_cmd_idx.has_value());
  CHECK(*last_vle_idx < *vstart_cmd_idx);
  CHECK(*last_vle_idx < *mcycle_cmd_idx);
}

TEST_CASE("B4: resume with HYBRID_FLAG_FP and drained FS=Off still writes "
          "mstatus with FS != Off so FPR abstract writes are accepted")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_FP;
  s.mstatus = 0;                  // FS = 00 (Off)

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Find the abstract write that targets mstatus (regno = 0x300) and verify
  // FS (bits 14:13) was forced non-zero. The drained mstatus has FS=Off but
  // the hart needs FS != Off to accept abstract FPR writes; the gate must
  // OR in FS=Initial without altering the wire-format state.mstatus.
  std::optional<uint32_t> mstatus_low32;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x300)
        && ((op.value >> 16) & 1u)) {
      REQUIRE(i >= 2);
      mstatus_low32 = bus.ops[i - 2].value;
      break;
    }
  }
  REQUIRE(mstatus_low32.has_value());
  CHECK((*mstatus_low32 & 0x6000u) != 0u);
}

