1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "hybrid/v_regfile_xfer.hpp"
12	
13	#include <algorithm>
14	#include <array>
15	#include <cstdint>
16	#include <span>
17	
18	namespace hybrid
19	{
20	
21	class StateDrain
22	{
23	public:
24	  using RD = ResumeDriver;
25	
26	  explicit StateDrain(DmiBus& bus)
27	      : bus_{bus}
28	  {}
29	
30	  // F16: stash the warmup-window snapshot (mcycle, minstret captured K
31	  // retires after vsim entry). Both drain() and drain_with_passthrough()
32	  // copy these into the returned state. Zero when MeasureStartSnapshot
33	  // never fired (K=0 or workload exited inside the warmup window).
34	  void set_warmup_snapshot(uint64_t mcycle, uint64_t minstret)
35	  {
36	    warmup_mcycle_   = mcycle;
37	    warmup_minstret_ = minstret;
38	  }
39	
40	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
41	  // drain_with_passthrough when the QEMU 1 snapshot is available.
42	  auto drain() -> hybrid_state_v1
43	  {
44	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
45	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
46	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
47	                   "StateDrain halt");
48	
49	    hybrid_state_v1 state{};
50	    state.magic   = HYBRID_STATE_MAGIC;
51	    state.version = HYBRID_STATE_VERSION;
52	    state.flags   = HYBRID_FLAG_RV64;
53	    // L6: dcsr.prv holds the privilege the hart was in when the halt landed.
54	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
55	                                  "StateDrain DCSR") & 0x3u;
56	
57	    for (uint16_t i = 1; i < 32; ++i)
58	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
59	
60	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
61	    state.mcycle_at_measure_start   = warmup_mcycle_;
62	    state.minstret_at_measure_start = warmup_minstret_;
63	    return state;
64	  }
65	
66	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
67	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
68	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
69	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
70	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
71	  // and vreg remain pass-through (read-only / too large for DM).
72	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
73	  // contribution would otherwise be discarded as the passthrough preserves
74	  // QEMU1's pre-handoff value.
75	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
76	  {
77	    auto state       = input;
78	    const auto fresh = drain();
79	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
80	              std::begin(state.gpr) + 1);
81	    state.pc   = fresh.pc;
82	    state.priv = fresh.priv;  // L6: privilege at the exit halt, not QEMU1's
83	
84	    if (input.flags & HYBRID_FLAG_FP) {
85	      for (uint16_t i = 0; i < 32; ++i)
86	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
87	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
88	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
89	    }
90	
91	    if (input.flags & HYBRID_FLAG_V) {
92	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
93	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
94	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
95	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
96	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
97	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
98	    }
99	
100	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
101	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
102	    // dropped and the stale QEMU1 value passes through into the drained state.
103	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
104	
105	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
106	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
107	
108	    // V data regfile: dump v0..v31 to the shared scratch region via the
109	    // Program Buffer LAST -- after every architectural read above -- so the
110	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
111	    // cannot corrupt the values already captured. The simulator's
112	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
113	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
114	    if (input.flags & HYBRID_FLAG_V)
115	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, input.vlenb,
116	                      /*load=*/false);
117	
118	    state.mcycle_at_measure_start   = warmup_mcycle_;
119	    state.minstret_at_measure_start = warmup_minstret_;
120	    return state;
121	  }
122	
123	  // cosim_roi F1: checkpoint drain. Same capture as drain_with_passthrough,
124	  // but the hart must keep running afterwards. The exit drain may clobber
125	  // freely (the run ends there); a checkpoint must undo the dump sweep's
126	  // clobbers -- vtype/vl/vstart and the x5/x6/x7 scratch -- from the freshly
127	  // drained values, then resume. DPC is untouched, so the hart continues
128	  // exactly where the halt landed.
129	  auto drain_checkpoint(const hybrid_state_v1& input) -> hybrid_state_v1
130	  {
131	    const auto state = drain_with_passthrough(input);
132	
133	    if (input.flags & HYBRID_FLAG_V)
134	      undo_v_sweep_clobbers(state);
135	
136	    bus_.write(RD::kDmcontrol,
137	               RD::kDmcontrolDmactive | RD::kDmcontrolResumereq);
138	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllresumeack,
139	                   "StateDrain checkpoint resume");
140	    return state;
141	  }
142	
143	  // cosim_redesign F1: full drain with NO QEMU1 passthrough input -- every
144	  // populated field comes from the hart. Flags are probed from misa, vlenb
145	  // from its CSR, and the trap CSR block + PMP are read via (tolerant)
146	  // Abstract Commands. Non-destructive: the V dump sweep's clobbers are
147	  // undone and a force-enabled FS/VS is restored, so the hart can continue
148	  // (lock-step record loop). The hart is left HALTED -- the caller decides
149	  // between step, resume, or exit.
150	  auto drain_full() -> hybrid_state_v1
151	  {
152	    auto state = drain();  // halt + GPRs/pc/priv, flags = RV64
153	
154	    const uint64_t misa =
155	      read_register_64(bus_, regno_csr(RD::kCsrMisa), "StateDrain misa");
156	    if (misa & (kMisaF | kMisaD)) state.flags |= HYBRID_FLAG_FP;
157	    if (misa & kMisaV) state.flags |= HYBRID_FLAG_V;
158	
159	    state.mstatus  = read_register_64(bus_, regno_csr(RD::kCsrMstatus));
160	    state.mepc     = read_register_64(bus_, regno_csr(RD::kCsrMepc));
161	    state.mtvec    = read_register_64(bus_, regno_csr(RD::kCsrMtvec));
162	    state.mcause   = read_register_64(bus_, regno_csr(RD::kCsrMcause));
163	    state.mtval    = read_register_64(bus_, regno_csr(RD::kCsrMtval));
164	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
165	    state.medeleg  = read_register_64(bus_, regno_csr(RD::kCsrMedeleg));
166	    state.mideleg  = read_register_64(bus_, regno_csr(RD::kCsrMideleg));
167	    state.mip      = read_register_64(bus_, regno_csr(RD::kCsrMip));
168	    state.mie      = read_register_64(bus_, regno_csr(RD::kCsrMie));
169	    state.satp     = read_register_64(bus_, regno_csr(RD::kCsrSatp));
170	
171	    // PMP: read_register_64 maps a missing entry to 0 (tolerant), matching
172	    // the resume side's tolerant writes. Odd pmpcfg CSRs do not exist on
173	    // RV64 and stay zero.
174	    for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
175	      state.pmpaddr[i] =
176	        read_register_64(bus_, regno_csr(RD::kCsrPmpaddr0 + i));
177	    for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
178	      state.pmpcfg[i] =
179	        read_register_64(bus_, regno_csr(RD::kCsrPmpcfg0 + i));
180	
181	    // FS/VS at Off NACKs the FPR / V accesses below. Force the minimal
182	    // enable for the reads, restore the architectural mstatus afterwards;
183	    // the record keeps the original value either way.
184	    uint64_t live_mstatus = state.mstatus;
185	    if ((state.flags & HYBRID_FLAG_FP)
186	        && (live_mstatus & RD::kMstatusFsMask) == 0)
187	      live_mstatus |= RD::kMstatusFsInitial;
188	    if ((state.flags & HYBRID_FLAG_V)
189	        && (live_mstatus & RD::kMstatusVsMask) == 0)
190	      live_mstatus |= RD::kMstatusVsInitial;
191	    const bool mstatus_forced = live_mstatus != state.mstatus;
192	    if (mstatus_forced) write_csr_tolerant(RD::kCsrMstatus, live_mstatus);
193	
194	    if (state.flags & HYBRID_FLAG_FP) {
195	      for (uint16_t i = 0; i < 32; ++i)
196	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
197	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
198	    }
199	
200	    if (state.flags & HYBRID_FLAG_V) {
201	      state.vlenb  = read_register_64(bus_, regno_csr(RD::kCsrVlenb));
202	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
203	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
204	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
205	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
206	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
207	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
208	    }
209	
210	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
211	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
212	
213	    // V data dump LAST (same reasoning as drain_with_passthrough), then undo
214	    // the sweep's clobbers so the hart can keep executing.
215	    if (state.flags & HYBRID_FLAG_V) {
216	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, state.vlenb,
217	                      /*load=*/false);
218	      undo_v_sweep_clobbers(state);
219	    }
220	
221	    if (mstatus_forced) write_csr_tolerant(RD::kCsrMstatus, state.mstatus);
222	    return state;
223	  }
224	
225	private:
226	  // misa extension letters used by the drain_full flag probe.
227	  static constexpr uint64_t kMisaD = 1ULL << 3;
228	  static constexpr uint64_t kMisaF = 1ULL << 5;
229	  static constexpr uint64_t kMisaV = 1ULL << 21;
230	
231	  // Undo the dump sweep's clobbers -- vtype/vl/vstart and the x5/x6/x7
232	  // scratch -- from the freshly drained values, so the hart can continue.
233	  void undo_v_sweep_clobbers(const hybrid_state_v1& state)
234	  {
235	    // vtype+vl atomically via vsetvl (direct vtype write sets vill; vl is
236	    // read-only), staged in x5/x6 like the ResumeDriver Tier-B restore.
237	    write_register_abstract(bus_, regno_gpr(5), state.vl);
238	    write_register_abstract(bus_, regno_gpr(6), state.vtype);
239	    const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
240	    exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
241	    // vstart AFTER vsetvl (vsetvl zeroes it), via PB csrrw staged in x7 --
242	    // still scratch until the GPR rewrite below.
243	    write_register_abstract(bus_, regno_gpr(7), state.vstart);
244	    const std::array<uint32_t, 1> pb_vstart = {
245	      encode_csrrw(0, RD::kCsrVstart, 7) };
246	    exec_progbuf(bus_, std::span<const uint32_t>{pb_vstart});
247	    // Scratch GPRs back to the drained architectural values.
248	    write_register_abstract(bus_, regno_gpr(5), state.gpr[5]);
249	    write_register_abstract(bus_, regno_gpr(6), state.gpr[6]);
250	    write_register_abstract(bus_, regno_gpr(7), state.gpr[7]);
251	  }
252	
253	  // Abstract CSR write that clears a sticky cmderr instead of blocking the
254	  // remaining drain (mirror of ResumeDriver::write_csr_tolerant).
255	  void write_csr_tolerant(uint16_t csr, uint64_t value)
256	  {
257	    write_register_abstract(bus_, regno_csr(csr), value);
258	    if ((bus_.read(RD::kAbstractcs) & RD::kAbstractcsCmderrMask) != 0u)
259	      bus_.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
260	  }
261	
262	  DmiBus& bus_;
263	  uint64_t warmup_mcycle_   = 0;  // F16: zero when warmup boundary never fired
264	  uint64_t warmup_minstret_ = 0;
265	};
266	
267	}  // namespace hybrid
