1	// Oracle differential compare. See state_diff.hpp for the policy.
2	#include "state_diff.hpp"
3	
4	#include <cstdio>
5	#include <string>
6	
7	#include "cli.hpp"
8	#include "state.hpp"
9	
10	namespace andes_sim {
11	
12	namespace {
13	
14	void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
15	         unsigned long long got) {
16	  ++r.compared;
17	  if (ref != got) r.diffs.push_back({field, ref, got});
18	}
19	
20	}  // namespace
21	
22	DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
23	                       bool compare_trap_cause) {
24	  DiffReport r;
25	
26	  cmp(r, "magic", ref.magic, got.magic);
27	  cmp(r, "version", ref.version, got.version);
28	  cmp(r, "flags", ref.flags, got.flags);
29	  cmp(r, "hart_id", ref.hart_id, got.hart_id);
30	  cmp(r, "priv", ref.priv, got.priv);
31	  cmp(r, "pc", ref.pc, got.pc);
32	
33	  // Lock-step only: the trap triple's two well-defined members. A divergent
34	  // trap shows here (and at the handler pc on the next record); mtval/mstatus
35	  // stay out to avoid implementation-defined false positives.
36	  if (compare_trap_cause) {
37	    cmp(r, "mepc", ref.mepc, got.mepc);
38	    cmp(r, "mcause", ref.mcause, got.mcause);
39	  }
40	
41	  // L23: mscratch round-trips through the hybrid handoff (restored at resume,
42	  // re-read at drain), so the hybrid verify compares it. The lock-step path is
43	  // reset-vs-reset, where mscratch's reset value is implementation-defined
44	  // (like mstatus/mtval), so it stays excluded there.
45	  if (!compare_trap_cause)
46	    cmp(r, "mscratch", ref.mscratch, got.mscratch);
47	
48	  for (int i = 0; i < 32; ++i)
49	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
50	
51	  if (ref.flags & HYBRID_FLAG_FP) {
52	    for (int i = 0; i < 32; ++i)
53	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
54	    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
55	  }
56	
57	  if (ref.flags & HYBRID_FLAG_V) {
58	    cmp(r, "vstart", ref.vstart, got.vstart);
59	    cmp(r, "vtype", ref.vtype, got.vtype);
60	    cmp(r, "vl", ref.vl, got.vl);
61	    cmp(r, "vlenb", ref.vlenb, got.vlenb);
62	    cmp(r, "vxsat", ref.vxsat, got.vxsat);
63	    cmp(r, "vxrm", ref.vxrm, got.vxrm);
64	    cmp(r, "vcsr", ref.vcsr, got.vcsr);
65	
66	    // One compared "field" per vector register; report the first differing
67	    // byte as "v<i>[<byte>]".
68	    for (int i = 0; i < 32; ++i) {
69	      ++r.compared;
70	      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
71	      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
72	      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
73	        if (a[j] != b[j]) {
74	          r.diffs.push_back({"v" + std::to_string(i) + "[" +
75	                                 std::to_string(j) + "]",
76	                             a[j], b[j]});
77	          break;
78	        }
79	      }
80	    }
81	  }
82	
83	  return r;
84	}
85	
86	void print_diff_report(const DiffReport& r) {
87	  for (const FieldDiff& d : r.diffs)
88	    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
89	                d.ref, d.got);
90	  if (r.ok()) {
91	    std::printf(
92	        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
93	        "excluded)\n",
94	        r.compared);
95	  } else {
96	    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
97	                r.diffs.size(), r.compared);
98	  }
99	}
100	
101	// `andes-sim state-diff <ref.bin> <got.bin>` -- the file-based surface of
102	// diff_states for shell harnesses (tests/e2e.sh VERIFY=1). rc: 0 match,
103	// 1 mismatch, 2 usage/read error.
104	int cmd_state_diff(const Cli& cli) {
105	  if (cli.positional.size() != 2) {
106	    std::fputs("usage: andes-sim state-diff <ref.bin> <got.bin>\n", stderr);
107	    return 2;
108	  }
109	  const StateFile ref = read_state_file(cli.positional[0]);
110	  if (!ref.ok()) {
111	    std::fprintf(stderr, "andes-sim state-diff: %s\n", ref.error.c_str());
112	    return 2;
113	  }
114	  const StateFile got = read_state_file(cli.positional[1]);
115	  if (!got.ok()) {
116	    std::fprintf(stderr, "andes-sim state-diff: %s\n", got.error.c_str());
117	    return 2;
118	  }
119	  const DiffReport r = diff_states(ref.st, got.st);
120	  print_diff_report(r);
121	  return r.ok() ? 0 : 1;
122	}
