311	
312	  // DM holds post-vsim values.
313	  bus.regfile[hybrid::regno_csr(RD::kCsrVstart)] = 7;
314	  bus.regfile[hybrid::regno_csr(RD::kCsrVxsat)]  = 1;
315	  bus.regfile[hybrid::regno_csr(RD::kCsrVxrm)]   = 2;
