318	  bus.regfile[hybrid::regno_csr(RD::kCsrVl)]     = 16;
319	
320	  hybrid_state_v1 input{};
321	  input.magic   = HYBRID_STATE_MAGIC;
322	  input.version = HYBRID_STATE_VERSION;
323	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
324	  input.priv    = 3;
325	  // Stale QEMU1 values that must be overwritten by DM reads.
326	  input.vstart = 99;
327	  input.vxsat  = 88;
328	  input.vxrm   = 77;
