344	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: V CSR reads issued after GPR reads")
345	{
346	  RecordingBus bus;
347	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
348	
349	  hybrid_state_v1 input{};
350	  input.magic   = HYBRID_STATE_MAGIC;
351	  input.version = HYBRID_STATE_VERSION;
352	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
353	  input.priv    = 3;
354	
355	  hybrid::StateDrain drain(bus);
356	  (void) drain.drain_with_passthrough(input);
357	
358	  // Find the last GPR COMMAND read and the first V CSR COMMAND read.
359	  std::optional<std::size_t> last_gpr_cmd;
360	  std::optional<std::size_t> first_vcsr_cmd;
361	  const std::initializer_list<uint16_t> vcsr_regnos = {
362	    hybrid::regno_csr(RD::kCsrVstart),
363	    hybrid::regno_csr(RD::kCsrVxsat),
364	    hybrid::regno_csr(RD::kCsrVxrm),
365	    hybrid::regno_csr(RD::kCsrVcsr),
366	    hybrid::regno_csr(RD::kCsrVtype),
367	    hybrid::regno_csr(RD::kCsrVl),
368	  };
369	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
370	    const auto& op = bus.ops[i];
371	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
372	    const uint16_t regno = op.value & 0xFFFFu;
373	    // Only register READS matter here. The V-data dump sweep also issues GPR
374	    // WRITES (x5/x6/x7 scratch) at the end of drain; those are not the
375	    // architectural GPR reads this ordering check is about.
376	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
377	    if (is_read && regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
378	      last_gpr_cmd = i;
379	    for (uint16_t vcsr : vcsr_regnos)
380	      if (is_read && !first_vcsr_cmd && regno == vcsr)
381	        first_vcsr_cmd = i;
382	  }
383	  REQUIRE(last_gpr_cmd.has_value());
384	  REQUIRE(first_vcsr_cmd.has_value());
385	  CHECK(*last_gpr_cmd < *first_vcsr_cmd);
386	}
