418	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: PB dumps v0..v31 to scratch "
419	          "after the architectural counter/CSR reads")
420	{
421	  RecordingBus bus;
422	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
423	
424	  hybrid_state_v1 input{};
425	  input.magic   = HYBRID_STATE_MAGIC;
426	  input.version = HYBRID_STATE_VERSION;
427	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
428	  input.priv    = 3;
429	  input.vlenb   = 64;
430	
431	  hybrid::StateDrain drain(bus);
432	  (void) drain.drain_with_passthrough(input);
433	
434	  // (a) every v0..v31 is dumped via a vse8.v executed in the Program Buffer.
435	  std::vector<int> missing;
436	  std::optional<std::size_t> first_vse_idx;
437	  for (uint16_t v = 0; v < 32; ++v) {
438	    const uint32_t want = hybrid::encode_vse8_v(static_cast<uint8_t>(v), 7);
439	    std::optional<std::size_t> at;
440	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
441	      const auto& op = bus.ops[i];
442	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
443	          && op.value == want) { at = i; break; }
444	    }
445	    if (!at) { missing.push_back(v); continue; }
446	    if (!first_vse_idx || *at < *first_vse_idx) first_vse_idx = at;
447	  }
448	  CHECK(missing.empty());
449	  REQUIRE(first_vse_idx.has_value());
450	
451	  // (b) the dump sweep runs AFTER the mcycle/minstret reads, so the sweep's
452	  //     vse8.v insns (and any counter increments) cannot corrupt the drained
453	  //     counters. minstret(0xB02) is the last counter read before the sweep.
454	  std::optional<std::size_t> minstret_read_idx;
455	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
456	    const auto& op = bus.ops[i];
457	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
458	    const auto regno   = static_cast<uint16_t>(op.value & 0xFFFFu);
459	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
460	    if (is_read && regno == hybrid::regno_csr(0xB02)) minstret_read_idx = i;
461	  }
462	  REQUIRE(minstret_read_idx.has_value());
463	  CHECK(*minstret_read_idx < *first_vse_idx);
464	}
