466	// ---- drain_checkpoint (cosim_roi F1): drain, undo clobbers, resume ----
467	
468	namespace
469	{
470	
471	// Index of the last DMCONTROL write in the op log.
472	auto last_dmcontrol_write(const std::vector<DmiOp>& ops)
473	  -> std::optional<std::size_t>
474	{
475	  std::optional<std::size_t> at;
476	  for (std::size_t i = 0; i < ops.size(); ++i)
477	    if (ops[i].kind == DmiOp::Kind::Write && ops[i].reg == RD::kDmcontrol)
478	      at = i;
479	  return at;
480	}
481	
482	// Index of the last Program Buffer slot-0 write carrying `insn`.
483	auto last_progbuf_insn(const std::vector<DmiOp>& ops, uint32_t insn)
484	  -> std::optional<std::size_t>
485	{
486	  std::optional<std::size_t> at;
487	  for (std::size_t i = 0; i < ops.size(); ++i)
488	    if (ops[i].kind == DmiOp::Kind::Write && ops[i].reg == hybrid::kProgbuf0
489	        && ops[i].value == insn)
490	      at = i;
491	  return at;
492	}
493	
494	// All abstract-command WRITES to `regno`: (op index of COMMAND, 64-bit value
495	// assembled from the DATA0/DATA1 writes immediately preceding it).
496	auto abstract_writes_to(const std::vector<DmiOp>& ops, uint16_t regno)
497	  -> std::vector<std::pair<std::size_t, uint64_t>>
498	{
499	  std::vector<std::pair<std::size_t, uint64_t>> hits;
500	  uint32_t data0 = 0;
501	  uint32_t data1 = 0;
502	  for (std::size_t i = 0; i < ops.size(); ++i) {
503	    const auto& op = ops[i];
504	    if (op.kind != DmiOp::Kind::Write) continue;
505	    if (op.reg == RD::kData0) { data0 = op.value; continue; }
506	    if (op.reg == RD::kData1) { data1 = op.value; continue; }
507	    if (op.reg != RD::kCommand) continue;
508	    const auto target  = static_cast<uint16_t>(op.value & 0xFFFFu);
509	    const bool is_write = ((op.value >> 16) & 1u) != 0u;
510	    if (is_write && target == regno)
511	      hits.emplace_back(i, (static_cast<uint64_t>(data1) << 32) | data0);
512	  }
513	  return hits;
514	}
515	
516	}  // namespace
