581	TEST_CASE("drain_checkpoint with HYBRID_FLAG_V undoes the dump sweep's clobbers "
582	          "(vtype/vl via vsetvl, vstart, x5/x6/x7) before resuming")
583	{
584	  RecordingBus bus;
585	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
586	  bus.regfile[hybrid::regno_csr(RD::kCsrVl)]     = 16;
587	  bus.regfile[hybrid::regno_csr(RD::kCsrVtype)]  = 0xC1ULL;
588	  bus.regfile[hybrid::regno_csr(RD::kCsrVstart)] = 7;
589	  bus.regfile[hybrid::regno_gpr(5)] = 0x55;
590	  bus.regfile[hybrid::regno_gpr(6)] = 0x66;
591	  bus.regfile[hybrid::regno_gpr(7)] = 0x77;
592	
593	  hybrid_state_v1 input{};
594	  input.magic   = HYBRID_STATE_MAGIC;
595	  input.version = HYBRID_STATE_VERSION;
596	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
597	  input.priv    = 3;
598	  input.vlenb   = 64;
599	
600	  hybrid::StateDrain drain(bus);
601	  (void) drain.drain_checkpoint(input);
602	
603	  // (a) the undo vsetvl runs AFTER the dump sweep's last vse8.v (v31).
604	  const auto last_vse =
605	    last_progbuf_insn(bus.ops, hybrid::encode_vse8_v(31, 7));
606	  const auto undo_vsetvl =
607	    last_progbuf_insn(bus.ops, hybrid::encode_vsetvl(0, 5, 6));
608	  REQUIRE(last_vse.has_value());
609	  REQUIRE(undo_vsetvl.has_value());
610	  CHECK(*last_vse < *undo_vsetvl);
611	
612	  // (b) the undo vsetvl is staged with the DRAINED vl/vtype (not the sweep's
613	  //     e8/m1 constants): the last x5/x6 writes before it carry 16 / 0xC1.
614	  const auto x5_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(5));
615	  const auto x6_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(6));
616	  std::optional<uint64_t> staged_vl;
617	  std::optional<uint64_t> staged_vtype;
618	  for (const auto& [i, v] : x5_writes)
619	    if (i < *undo_vsetvl) staged_vl = v;
620	  for (const auto& [i, v] : x6_writes)
621	    if (i < *undo_vsetvl) staged_vtype = v;
622	  REQUIRE(staged_vl.has_value());
623	  REQUIRE(staged_vtype.has_value());
624	  CHECK(*staged_vl == 16u);
625	  CHECK(*staged_vtype == 0xC1ULL);
626	
627	  // (c) vstart is restored via PB csrrw after the vsetvl (which zeroes it).
628	  const auto vstart_csrrw =
629	    last_progbuf_insn(bus.ops, hybrid::encode_csrrw(0, RD::kCsrVstart, 7));
630	  REQUIRE(vstart_csrrw.has_value());
631	  CHECK(*undo_vsetvl < *vstart_csrrw);
632	  const auto x7_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(7));
633	  std::optional<uint64_t> staged_vstart;
634	  for (const auto& [i, v] : x7_writes)
635	    if (i > *undo_vsetvl && i < *vstart_csrrw) staged_vstart = v;
636	  REQUIRE(staged_vstart.has_value());
637	  CHECK(*staged_vstart == 7u);
638	
639	  // (d) the scratch GPRs are restored LAST with the drained values.
640	  REQUIRE(!x5_writes.empty());
641	  REQUIRE(!x6_writes.empty());
642	  REQUIRE(!x7_writes.empty());
643	  CHECK(x5_writes.back().second == 0x55u);
644	  CHECK(x6_writes.back().second == 0x66u);
645	  CHECK(x7_writes.back().second == 0x77u);
646	  CHECK(x5_writes.back().first > *vstart_csrrw);
647	
648	  // (e) resume comes after everything above.
649	  const auto resume = last_dmcontrol_write(bus.ops);
650	  REQUIRE(resume.has_value());
651	  CHECK((bus.ops[*resume].value & RD::kDmcontrolResumereq) != 0u);
652	  CHECK(*resume > x7_writes.back().first);
653	}
