791	    bus.regfile[hybrid::regno_csr(RD::kCsrPmpaddr0 + i)] = 0xb00ULL + i;
792	  for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
793	    bus.regfile[hybrid::regno_csr(RD::kCsrPmpcfg0 + i)] = 0xa00ULL + i;
794	
795	  hybrid::StateDrain drain(bus);
796	  const auto state = drain.drain_full();
797	
798	  CHECK(state.pmpaddr[0]  == 0xb00ULL);
799	  CHECK(state.pmpaddr[63] == 0xb3fULL);
800	  CHECK(state.pmpcfg[0]   == 0xa00ULL);
801	  CHECK(state.pmpcfg[14]  == 0xa0eULL);
802	}
803	
804	TEST_CASE("drain_full with V: dump sweep after counter reads, clobbers undone, "
805	          "and NO resume request issued")
806	{
807	  RecordingBus bus;
808	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
809	  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64 | kMisaV;
810	  bus.regfile[hybrid::regno_csr(0xC22)] = 32;
811	  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)] = 0x600ULL;  // VS on
812	  bus.regfile[hybrid::regno_csr(RD::kCsrVl)]     = 16;
813	  bus.regfile[hybrid::regno_csr(RD::kCsrVtype)]  = 0xC1ULL;
814	  bus.regfile[hybrid::regno_csr(RD::kCsrVstart)] = 7;
815	  bus.regfile[hybrid::regno_gpr(5)] = 0x55;
816	  bus.regfile[hybrid::regno_gpr(6)] = 0x66;
817	  bus.regfile[hybrid::regno_gpr(7)] = 0x77;
818	
819	  hybrid::StateDrain drain(bus);
820	  const auto state = drain.drain_full();
821	
822	  CHECK(state.vl    == 16u);
823	  CHECK(state.vtype == 0xC1ULL);
824	
825	  // Sweep present and after the minstret read.
826	  const auto last_vse =
827	    last_progbuf_insn(bus.ops, hybrid::encode_vse8_v(31, 7));
828	  REQUIRE(last_vse.has_value());
829	
830	  // Clobbers undone: undo vsetvl after the sweep, x5/x6/x7 rewritten last.
831	  const auto undo_vsetvl =
832	    last_progbuf_insn(bus.ops, hybrid::encode_vsetvl(0, 5, 6));
833	  REQUIRE(undo_vsetvl.has_value());
834	  CHECK(*last_vse < *undo_vsetvl);
835	  const auto x5_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(5));
836	  const auto x7_writes = abstract_writes_to(bus.ops, hybrid::regno_gpr(7));
837	  REQUIRE(!x5_writes.empty());
838	  REQUIRE(!x7_writes.empty());
839	  CHECK(x5_writes.back().second == 0x55u);
840	  CHECK(x7_writes.back().second == 0x77u);
841	
842	  // drain_full never resumes -- the caller (step loop / exit) decides.
843	  for (const auto& op : bus.ops) {
844	    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kDmcontrol)
845	      CHECK((op.value & RD::kDmcontrolResumereq) == 0u);
846	  }
847	}
848	
849	TEST_CASE("drain_full with FS off in mstatus: forces FS on for the FPR reads, "
850	          "then restores the original mstatus; the record keeps the original")
851	{
852	  RecordingBus bus;
853	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
854	  bus.regfile[hybrid::regno_csr(0x301)] = kMisaRv64 | kMisaF | kMisaD;
855	  bus.regfile[hybrid::regno_csr(RD::kCsrMstatus)] = 0x1800ULL;  // FS = Off
856	
857	  hybrid::StateDrain drain(bus);
858	  const auto state = drain.drain_full();
859	
860	  CHECK(state.mstatus == 0x1800ULL);
861	
862	  const auto ms_writes =
863	    abstract_writes_to(bus.ops, hybrid::regno_csr(RD::kCsrMstatus));
864	  REQUIRE(ms_writes.size() >= 2);
865	  // First write enables FS (Initial), final write restores the original.
866	  CHECK((ms_writes.front().second & RD::kMstatusFsMask) != 0u);
867	  CHECK(ms_writes.back().second == 0x1800ULL);
868	
869	  // The enable precedes the first FPR read.
870	  std::optional<std::size_t> first_fpr;
871	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
872	    const auto& op = bus.ops[i];
873	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
874	    const uint16_t regno = op.value & 0xFFFFu;
875	    if (regno >= hybrid::regno_fpr(0) && regno <= hybrid::regno_fpr(31)) {
876	      first_fpr = i;
877	      break;
878	    }
879	  }
880	  REQUIRE(first_fpr.has_value());
881	  CHECK(ms_writes.front().first < *first_fpr);
882	}
883	
884	TEST_CASE("L6: drain reads the hart privilege from dcsr.prv")
885	{
886	  RecordingBus bus;
887	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
888	  // dcsr: xdebugver=4, cause=3 (haltreq), prv=1 (S-mode at halt).
889	  bus.regfile[hybrid::regno_csr(RD::kCsrDcsr)] = 0x400000C1ULL;
890	
891	  hybrid::StateDrain drain(bus);
892	  const auto state = drain.drain();
893	
894	  CHECK(state.priv == 1u);
895	}
896	
897	TEST_CASE("L6: drain_with_passthrough reports the freshly drained privilege, "
898	          "not the QEMU1 snapshot's")
899	{
900	  RecordingBus bus;
901	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
902	  bus.regfile[hybrid::regno_csr(RD::kCsrDcsr)] = 0x40000000ULL;  // prv=0 (U)
903	
904	  hybrid_state_v1 input{};
905	  input.magic   = HYBRID_STATE_MAGIC;
906	  input.version = HYBRID_STATE_VERSION;
907	  input.flags   = HYBRID_FLAG_RV64;
908	  input.priv    = 3;  // stale: QEMU1 drained M before the ROI dropped to U
909	
910	  hybrid::StateDrain drain(bus);
911	  const auto state = drain.drain_with_passthrough(input);
912	
913	  CHECK(state.priv == 0u);
914	}
