// rt_csr_survival.S
//
// 2-phase guard (L23 + L24): the writable M-mode CSRs round-trip across the
// QEMU1 -> vsim handoff. A value stashed before the ROI is readable inside it
// (ResumeDriver restores the CSR) and a value written inside the ROI is
// captured at drain (StateDrain::drain_with_passthrough re-reads it).
//
// Covered CSRs:
//   L23  mscratch                 -- M-mode software scratch (pure read/write)
//   L24  mepc, mcause, mtval, mie -- writable trap/interrupt CSRs
//
// History: this fixture predates the 2-phase redesign. It used to read the CSRs
// back in a `phase_c` AFTER the exit marker and exit with the index of the
// first mismatch -- but once the QEMU2 handback leg was removed, vsim drains and
// exits AT the exit marker, so phase_c never ran and the guard was silently
// dead. The check now lives INSIDE the ROI, where the vsim leg actually runs.
//
// Two assertion mechanisms:
//   1. In-ROI self-check (works in the plain e2e harness, no --verify): read
//      the CSR back inside the ROI and `bne` against the stashed sentinel,
//      held in a callee-stable GPR which the GPR restore round-trips. On a
//      regressed restore the values differ, so the fixture spins -- vsim never
//      reaches the exit marker, times out, and the harness reports a failure.
//      Used only for mscratch/mepc/mie, whose values round-trip exactly.
//   2. --verify (VERIFY=1): the differential oracle compares the drained CSRs
//      against a pure-QEMU run. Used for mcause (WLRL) and mtval (WARL), whose
//      cross-engine legalisation could differ from a chosen sentinel; the
//      oracle path compares engine-against-engine instead of against a literal.
//
// Not asserted: mip (its pending bits are hardware-driven, not writable via
// csrw on an M-only core) and the S-mode CSRs medeleg/mideleg/satp (the default
// engine does not implement them). See docs/andes_sim_limitations.ipynb.

.section .text
.globl _start
_start:
    // Stash sentinels into the writable M-mode CSRs BEFORE the ROI (QEMU leg).
    // a1/a4/a5 are callee-stable GPRs the restore round-trips, so the in-ROI
    // reads below can compare against them.
    li      a1, 0xCAFEBABEDEADBEEF
    csrw    mscratch, a1            // L23 software scratch CSR

    li      a4, 0x0000000080002340  // aligned (bit0=0): mepc is WARL
    csrw    mepc, a4                // L24
    li      a5, 0x0000000000000888  // MSIE|MTIE|MEIE: standard M-mode mie bits
    csrw    mie, a5                 // L24 (mstatus.MIE stays 0: no trap is taken)

    // mcause (WLRL, a legal cause) + mtval (WARL): set for --verify coverage,
    // not in-ROI self-checked (cross-engine legalisation may differ from the
    // literal; the oracle compares engine-vs-engine instead).
    li      t1, 0x8000000000000007  // interrupt | code 7 (M timer): legal cause
    csrw    mcause, t1
    li      t1, 0x0000000080001234
    csrw    mtval, t1

    slti    x0, x0, 0x5A0           // ENTER ROI -> hand off to vsim

    // Read the round-trip CSRs back INSIDE the ROI: each must be restored.
    csrr    a0, mscratch
    bne     a0, a1, regress         // restore lost? spin -> timeout -> test FAIL
    csrr    a3, mepc
    bne     a3, a4, regress
    csrr    a6, mie
    bne     a6, a5, regress

    li      a2, 0xBADC0FFEE0DDF00D
    csrw    mscratch, a2            // overwrite; drain must re-read this value

    slti    x0, x0, 0x5A1           // EXIT ROI -> vsim drains the CSRs, exits 200

    // Unreached on hybrid (vsim stops at the exit marker). Engine-portable
    // SimControl exit so the same ELF still runs to completion standalone.
    li      t0, 0xe0080000
    sw      x0, 0(t0)
1:  j       1b

regress:
    j       regress                 // a restored CSR is wrong: hang -> harness FAIL

// Oracle differential compare (verify_oracle F2): field-wise diff of two
// drained hybrid_state_v1 records -- the QEMU oracle's exit-boundary drain
// (ref) against the hybrid run's vsim drain (got).
//
// Compare policy, fixed by what vsim's drain freshly reads (state_drain.hpp
// drain_with_passthrough):
//   strict:  magic/version/flags/hart_id/priv (identity), pc, gpr[0..31],
//            mepc/mcause (round-trip; also the lock-step trap-cause pair),
//            mscratch (L23) + mtval/mie (L24) -- round-trip M-mode CSRs
//            restored at resume + re-read at drain, hybrid policy only; fpr
//            [0..31] under FLAG_FP; vstart/vtype/vl/vlenb/vxsat/vxrm/vcsr and
//            the vreg bytes under FLAG_V.
//   skipped: mstatus, mtvec, medeleg, mideleg, mip, satp, pmpcfg[], pmpaddr[].
//            mtvec/medeleg/mideleg/satp/PMP are passthrough on the vsim side
//            (copied from QEMU1's ENTRY snapshot, never re-read). mip IS
//            re-read but excluded here -- its pending bits are hardware-driven
//            and diverge between the engines' clocks. mstatus is excluded for
//            its dirty/impl-defined bits.
//   masked:  mcycle, minstret, mcycle/minstret_at_measure_start -- the
//            engines count cycles/insns differently by design.
#ifndef ANDES_SIM_STATE_DIFF_HPP
#define ANDES_SIM_STATE_DIFF_HPP

#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// One strictly-compared field that differs: "pc", "x5", "f31", "vl",
// "v3[7]" (register + byte offset), "flags", ...
struct FieldDiff {
  std::string field;
  unsigned long long ref = 0;
  unsigned long long got = 0;
};

struct DiffReport {
  int compared = 0;  // count of strictly compared fields
  std::vector<FieldDiff> diffs;
  bool ok() const { return diffs.empty(); }
};

// compare_trap_cause (cosim_redesign F6, lock-step): restrict the M-mode CSR
// set to the trap-cause pair mepc/mcause -- the well-defined fields that reveal
// a mishandled trap -- and DROP the hybrid-only round-trip CSRs mscratch/mtval/
// mie (reset-vs-reset is implementation-defined in lock-step). Still EXCLUDES
// mtval (implementation-defined for illegal insns) and mstatus (dirty-bit
// differences). Default false = the hybrid-ROI policy above (mepc/mcause +
// mscratch/mtval/mie all round-trip and are compared).
DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
                       bool compare_trap_cause = false);

// Print `r` as "[state-diff] ..." lines: one per mismatch, then the
// PASS/FAIL verdict. Shared by the state-diff subcommand and run --verify.
void print_diff_report(const DiffReport& r);

}  // namespace andes_sim

#endif  // ANDES_SIM_STATE_DIFF_HPP

// Oracle differential compare. See state_diff.hpp for the policy.
#include "state_diff.hpp"

#include <cstdio>
#include <string>

#include "cli.hpp"
#include "state.hpp"

namespace andes_sim {

namespace {

void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
         unsigned long long got) {
  ++r.compared;
  if (ref != got) r.diffs.push_back({field, ref, got});
}

}  // namespace

DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
                       bool compare_trap_cause) {
  DiffReport r;

  cmp(r, "magic", ref.magic, got.magic);
  cmp(r, "version", ref.version, got.version);
  cmp(r, "flags", ref.flags, got.flags);
  cmp(r, "hart_id", ref.hart_id, got.hart_id);
  cmp(r, "priv", ref.priv, got.priv);
  cmp(r, "pc", ref.pc, got.pc);

  // mepc/mcause: compared in BOTH policies. In the trap-free hybrid ROI they
  // round-trip (L24: restored at resume, re-read at drain); in the lock-step
  // trap path they are the trap-cause pair that reveals a divergent trap (the
  // handler pc shows on the next record). mtval/mstatus stay out of lock-step
  // (implementation-defined on a real trap / dirty bits -> false positives).
  cmp(r, "mepc", ref.mepc, got.mepc);
  cmp(r, "mcause", ref.mcause, got.mcause);

  // Round-trip M-mode CSRs, hybrid policy only: mscratch (L23) and mtval/mie
  // (L24) are restored at resume and re-read at drain, so a trap-free ROI must
  // match the oracle on them. The lock-step path is reset-vs-reset
  // (implementation-defined reset values), so it excludes them. mip is excluded
  // in BOTH: its pending bits are hardware/platform-driven (timer/external) and
  // diverge between QEMU's functional clock and vsim's cycle clock even with no
  // trap (it still round-trips into the drained record, just not the verifier).
  if (!compare_trap_cause) {
    cmp(r, "mscratch", ref.mscratch, got.mscratch);
    cmp(r, "mtval", ref.mtval, got.mtval);
    cmp(r, "mie", ref.mie, got.mie);
  }

  for (int i = 0; i < 32; ++i)
    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);

  if (ref.flags & HYBRID_FLAG_FP) {
    for (int i = 0; i < 32; ++i)
      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
  }

  if (ref.flags & HYBRID_FLAG_V) {
    cmp(r, "vstart", ref.vstart, got.vstart);
    cmp(r, "vtype", ref.vtype, got.vtype);
    cmp(r, "vl", ref.vl, got.vl);
    cmp(r, "vlenb", ref.vlenb, got.vlenb);
    cmp(r, "vxsat", ref.vxsat, got.vxsat);
    cmp(r, "vxrm", ref.vxrm, got.vxrm);
    cmp(r, "vcsr", ref.vcsr, got.vcsr);

    // One compared "field" per vector register; report the first differing
    // byte as "v<i>[<byte>]".
    for (int i = 0; i < 32; ++i) {
      ++r.compared;
      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
        if (a[j] != b[j]) {
          r.diffs.push_back({"v" + std::to_string(i) + "[" +
                                 std::to_string(j) + "]",
                             a[j], b[j]});
          break;
        }
      }
    }
  }

  return r;
}

void print_diff_report(const DiffReport& r) {
  for (const FieldDiff& d : r.diffs)
    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
                d.ref, d.got);
  if (r.ok()) {
    std::printf(
        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
        "excluded)\n",
        r.compared);
  } else {
    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
                r.diffs.size(), r.compared);
  }
}

// `andes-sim state-diff <ref.bin> <got.bin>` -- the file-based surface of
// diff_states for shell harnesses (tests/e2e.sh VERIFY=1). rc: 0 match,
// 1 mismatch, 2 usage/read error.
int cmd_state_diff(const Cli& cli) {
  if (cli.positional.size() != 2) {
    std::fputs("usage: andes-sim state-diff <ref.bin> <got.bin>\n", stderr);
    return 2;
  }
  const StateFile ref = read_state_file(cli.positional[0]);
  if (!ref.ok()) {
    std::fprintf(stderr, "andes-sim state-diff: %s\n", ref.error.c_str());
    return 2;
  }
  const StateFile got = read_state_file(cli.positional[1]);
  if (!got.ok()) {
    std::fprintf(stderr, "andes-sim state-diff: %s\n", got.error.c_str());
    return 2;
  }
  const DiffReport r = diff_states(ref.st, got.st);
  print_diff_report(r);
  return r.ok() ? 0 : 1;
}

}  // namespace andes_sim

