1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "hybrid/v_regfile_xfer.hpp"
12	
13	#include <algorithm>
14	#include <array>
15	#include <cstdint>
16	#include <span>
17	
18	namespace hybrid
19	{
20	
21	class StateDrain
22	{
23	public:
24	  using RD = ResumeDriver;
25	
26	  explicit StateDrain(DmiBus& bus)
27	      : bus_{bus}
28	  {}
29	
30	  // F16: stash the warmup-window snapshot (mcycle, minstret captured K
31	  // retires after vsim entry). Both drain() and drain_with_passthrough()
32	  // copy these into the returned state. Zero when MeasureStartSnapshot
33	  // never fired (K=0 or workload exited inside the warmup window).
34	  void set_warmup_snapshot(uint64_t mcycle, uint64_t minstret)
35	  {
36	    warmup_mcycle_   = mcycle;
37	    warmup_minstret_ = minstret;
38	  }
39	
40	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
41	  // drain_with_passthrough when the QEMU 1 snapshot is available.
42	  auto drain() -> hybrid_state_v1
43	  {
44	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
45	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
46	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
47	                   "StateDrain halt");
48	
49	    hybrid_state_v1 state{};
50	    state.magic   = HYBRID_STATE_MAGIC;
51	    state.version = HYBRID_STATE_VERSION;
52	    state.flags   = HYBRID_FLAG_RV64;
53	    // L6: dcsr.prv holds the privilege the hart was in when the halt landed.
54	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
55	                                  "StateDrain DCSR") & 0x3u;
56	
57	    for (uint16_t i = 1; i < 32; ++i)
58	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
59	
60	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
61	    state.mcycle_at_measure_start   = warmup_mcycle_;
62	    state.minstret_at_measure_start = warmup_minstret_;
63	    return state;
64	  }
65	
66	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
67	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
68	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
69	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
70	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
71	  // and vreg remain pass-through (read-only / too large for DM).
72	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
73	  // contribution would otherwise be discarded as the passthrough preserves
74	  // QEMU1's pre-handoff value.
75	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
76	  {
77	    auto state       = input;
78	    const auto fresh = drain();
79	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
80	              std::begin(state.gpr) + 1);
81	    state.pc   = fresh.pc;
82	    state.priv = fresh.priv;  // L6: privilege at the exit halt, not QEMU1's
83	
84	    if (input.flags & HYBRID_FLAG_FP) {
85	      for (uint16_t i = 0; i < 32; ++i)
86	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
87	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
88	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
89	    }
90	
91	    if (input.flags & HYBRID_FLAG_V) {
92	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
93	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
94	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
95	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
96	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
97	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
98	    }
99	
100	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
101	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
102	    // dropped and the stale QEMU1 value passes through into the drained state.
103	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
104	
105	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
106	    // restores them), so re-read them -- an in-ROI write must reach the drained
107	    // state instead of the stale QEMU1 passthrough value.
108	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
109	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
110	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
111	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
112	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
113	
114	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
115	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
116	
117	    // V data regfile: dump v0..v31 to the shared scratch region via the
118	    // Program Buffer LAST -- after every architectural read above -- so the
119	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
120	    // cannot corrupt the values already captured. The simulator's
121	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
122	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
123	    if (input.flags & HYBRID_FLAG_V)
124	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, input.vlenb,
125	                      /*load=*/false);
126	
127	    state.mcycle_at_measure_start   = warmup_mcycle_;
128	    state.minstret_at_measure_start = warmup_minstret_;
129	    return state;
130	  }
131	
132	  // cosim_roi F1: checkpoint drain. Same capture as drain_with_passthrough,
133	  // but the hart must keep running afterwards. The exit drain may clobber
134	  // freely (the run ends there); a checkpoint must undo the dump sweep's
135	  // clobbers -- vtype/vl/vstart and the x5/x6/x7 scratch -- from the freshly
136	  // drained values, then resume. DPC is untouched, so the hart continues
137	  // exactly where the halt landed.
138	  auto drain_checkpoint(const hybrid_state_v1& input) -> hybrid_state_v1
139	  {
140	    const auto state = drain_with_passthrough(input);
141	
142	    if (input.flags & HYBRID_FLAG_V)
143	      undo_v_sweep_clobbers(state);
144	
145	    bus_.write(RD::kDmcontrol,
146	               RD::kDmcontrolDmactive | RD::kDmcontrolResumereq);
147	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllresumeack,
148	                   "StateDrain checkpoint resume");
149	    return state;
150	  }
151	
152	  // cosim_redesign F1: full drain with NO QEMU1 passthrough input -- every
153	  // populated field comes from the hart. Flags are probed from misa, vlenb
154	  // from its CSR, and the trap CSR block + PMP are read via (tolerant)
155	  // Abstract Commands. Non-destructive: the V dump sweep's clobbers are
156	  // undone and a force-enabled FS/VS is restored, so the hart can continue
157	  // (lock-step record loop). The hart is left HALTED -- the caller decides
158	  // between step, resume, or exit.
159	  auto drain_full() -> hybrid_state_v1
160	  {
161	    auto state = drain();  // halt + GPRs/pc/priv, flags = RV64
162	
163	    const uint64_t misa =
164	      read_register_64(bus_, regno_csr(RD::kCsrMisa), "StateDrain misa");
165	    if (misa & (kMisaF | kMisaD)) state.flags |= HYBRID_FLAG_FP;
166	    if (misa & kMisaV) state.flags |= HYBRID_FLAG_V;
167	
168	    state.mstatus  = read_register_64(bus_, regno_csr(RD::kCsrMstatus));
169	    state.mepc     = read_register_64(bus_, regno_csr(RD::kCsrMepc));
170	    state.mtvec    = read_register_64(bus_, regno_csr(RD::kCsrMtvec));
171	    state.mcause   = read_register_64(bus_, regno_csr(RD::kCsrMcause));
172	    state.mtval    = read_register_64(bus_, regno_csr(RD::kCsrMtval));
173	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
174	    state.medeleg  = read_register_64(bus_, regno_csr(RD::kCsrMedeleg));
175	    state.mideleg  = read_register_64(bus_, regno_csr(RD::kCsrMideleg));
176	    state.mip      = read_register_64(bus_, regno_csr(RD::kCsrMip));
177	    state.mie      = read_register_64(bus_, regno_csr(RD::kCsrMie));
178	    state.satp     = read_register_64(bus_, regno_csr(RD::kCsrSatp));
179	
180	    // PMP: read_register_64 maps a missing entry to 0 (tolerant), matching
181	    // the resume side's tolerant writes. Odd pmpcfg CSRs do not exist on
182	    // RV64 and stay zero.
183	    for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
184	      state.pmpaddr[i] =
185	        read_register_64(bus_, regno_csr(RD::kCsrPmpaddr0 + i));
186	    for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
187	      state.pmpcfg[i] =
188	        read_register_64(bus_, regno_csr(RD::kCsrPmpcfg0 + i));
189	
190	    // FS/VS at Off NACKs the FPR / V accesses below. Force the minimal
191	    // enable for the reads, restore the architectural mstatus afterwards;
192	    // the record keeps the original value either way.
193	    uint64_t live_mstatus = state.mstatus;
194	    if ((state.flags & HYBRID_FLAG_FP)
195	        && (live_mstatus & RD::kMstatusFsMask) == 0)
196	      live_mstatus |= RD::kMstatusFsInitial;
197	    if ((state.flags & HYBRID_FLAG_V)
198	        && (live_mstatus & RD::kMstatusVsMask) == 0)
199	      live_mstatus |= RD::kMstatusVsInitial;
200	    const bool mstatus_forced = live_mstatus != state.mstatus;
201	    if (mstatus_forced) write_csr_tolerant(RD::kCsrMstatus, live_mstatus);
202	
203	    if (state.flags & HYBRID_FLAG_FP) {
204	      for (uint16_t i = 0; i < 32; ++i)
205	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
206	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
207	    }
208	
209	    if (state.flags & HYBRID_FLAG_V) {
210	      state.vlenb  = read_register_64(bus_, regno_csr(RD::kCsrVlenb));
211	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
212	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
213	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
214	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
215	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
216	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
217	    }
218	
219	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
220	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
221	
222	    // V data dump LAST (same reasoning as drain_with_passthrough), then undo
223	    // the sweep's clobbers so the hart can keep executing.
224	    if (state.flags & HYBRID_FLAG_V) {
225	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, state.vlenb,
226	                      /*load=*/false);
227	      undo_v_sweep_clobbers(state);
228	    }
229	
230	    if (mstatus_forced) write_csr_tolerant(RD::kCsrMstatus, state.mstatus);
231	    return state;
232	  }
233	
234	private:
235	  // misa extension letters used by the drain_full flag probe.
236	  static constexpr uint64_t kMisaD = 1ULL << 3;
237	  static constexpr uint64_t kMisaF = 1ULL << 5;
238	  static constexpr uint64_t kMisaV = 1ULL << 21;
239	
240	  // Undo the dump sweep's clobbers -- vtype/vl/vstart and the x5/x6/x7
241	  // scratch -- from the freshly drained values, so the hart can continue.
242	  void undo_v_sweep_clobbers(const hybrid_state_v1& state)
243	  {
244	    // vtype+vl atomically via vsetvl (direct vtype write sets vill; vl is
245	    // read-only), staged in x5/x6 like the ResumeDriver Tier-B restore.
246	    write_register_abstract(bus_, regno_gpr(5), state.vl);
247	    write_register_abstract(bus_, regno_gpr(6), state.vtype);
248	    const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
249	    exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
250	    // vstart AFTER vsetvl (vsetvl zeroes it), via PB csrrw staged in x7 --
251	    // still scratch until the GPR rewrite below.
252	    write_register_abstract(bus_, regno_gpr(7), state.vstart);
253	    const std::array<uint32_t, 1> pb_vstart = {
254	      encode_csrrw(0, RD::kCsrVstart, 7) };
255	    exec_progbuf(bus_, std::span<const uint32_t>{pb_vstart});
256	    // Scratch GPRs back to the drained architectural values.
257	    write_register_abstract(bus_, regno_gpr(5), state.gpr[5]);
258	    write_register_abstract(bus_, regno_gpr(6), state.gpr[6]);
259	    write_register_abstract(bus_, regno_gpr(7), state.gpr[7]);
260	  }
261	
262	  // Abstract CSR write that clears a sticky cmderr instead of blocking the
263	  // remaining drain (mirror of ResumeDriver::write_csr_tolerant).
264	  void write_csr_tolerant(uint16_t csr, uint64_t value)
265	  {
266	    write_register_abstract(bus_, regno_csr(csr), value);
267	    if ((bus_.read(RD::kAbstractcs) & RD::kAbstractcsCmderrMask) != 0u)
268	      bus_.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
269	  }
270	
271	  DmiBus& bus_;
272	  uint64_t warmup_mcycle_   = 0;  // F16: zero when warmup boundary never fired
273	  uint64_t warmup_minstret_ = 0;
274	};
275	
276	}  // namespace hybrid
