    addi t0, t0, -t0
    addi t0, t0, 1              // keep t0 = counter (undo the mul side-effect)
    blt  t0, t1, roi_loop

    slti x0, x0, 0x5A1          // EXIT ROI

    li   t0, 0xe0080000
    sw   x0, 0(t0)
