// L26/F3: refuse a run whose static image would extend into the reserved
// V-transport scratch page. Scheme D parks the scratch at ram_base +
// --mem-size (the mmap's extra page); a PT_LOAD segment reaching there means
// the ELF was linked for more RAM than --mem-size grants, and QEMU would load
// it straight onto the scratch -> silent corruption. ram_base is the fixed
// andes_ae350 DRAM base (0; see L10 for the machine-base assumption). The
// check is skipped when the ELF cannot be read here -- downstream reports it.
{
  std::string e;
  const uint64_t top = elf_load_top(elf_path, e);
  const uint64_t scratch_gpa = static_cast<uint64_t>(mem);  // ram_base 0 + mem
  if (e.empty() && top > scratch_gpa) {
    char msg[256];
    std::snprintf(msg, sizeof(msg),
                  "ELF static image ends at 0x%llx, overlapping the reserved "
                  "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
                  "; raise --mem-size or shrink the image",
                  static_cast<unsigned long long>(top),
                  static_cast<unsigned long long>(scratch_gpa));
    return fail(msg);
  }
}

