  return true;
}

// Slurp `path` and validate its ELFCLASS64 header into `eh`. Returns false and
// sets `err` (unreadable / not-ELF / not-RV64) on failure, clears `err` on ok.
// Shared prologue for every ELF reader below.
bool read_elf64_header(const std::string& path, std::vector<char>& buf,
                       Elf64_Ehdr& eh, std::string& err) {
  err.clear();
  if (!slurp(path, buf)) {
    err = "cannot read ELF '" + path + "'";
    return false;
  }
  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
    err = "not an ELF file: " + path;
    return false;
  }
  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
    err = "not an RV64 (ELFCLASS64) file: " + path;
    return false;
  }
  return true;
}

}  // namespace

std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
                       std::string& err) {
  err.clear();

  // A "0x"/"0X" address is used verbatim with the prefix stripped (roi.sh
  // `${boundary#0[xX]}`); the .symtab is never touched.
  if (boundary.starts_with("0x") || boundary.starts_with("0X")) {
    std::string addr = boundary.substr(2);
    if (addr.empty()) {
      err = "malformed address '" + boundary + "'";
      return "";
    }
    return addr;
  }

  std::vector<char> buf;
  Elf64_Ehdr eh;
  if (!read_elf64_header(elf_path, buf, eh, err)) return "";

  // Scan section headers for a symbol table; resolve names through its linked
  // string table (sh_link).
  for (unsigned i = 0; i < eh.e_shnum; ++i) {
    Elf64_Shdr sym_sh;
    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
      break;
    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;

    Elf64_Shdr str_sh;
    if (sym_sh.sh_link >= eh.e_shnum ||
        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
              str_sh))
      continue;

    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
    for (size_t s = 0; s < nsym; ++s) {
      Elf64_Sym sym;
      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
      if (sym.st_shndx == SHN_UNDEF) continue;  // --defined-only

      const size_t noff = str_sh.sh_offset + sym.st_name;
      if (noff >= buf.size()) continue;
      const char* name = buf.data() + noff;
      const size_t avail = buf.size() - noff;
      if (::strnlen(name, avail) == avail) continue;  // unterminated in bounds
      if (boundary == name) return to_hex(sym.st_value);
    }
  }

  err = "symbol '" + boundary + "' not defined in " + elf_path;
  return "";
}

uint64_t elf_entry(const std::string& elf_path, std::string& err) {
  std::vector<char> buf;
  Elf64_Ehdr eh;
  if (!read_elf64_header(elf_path, buf, eh, err)) return 0;
  return eh.e_entry;
}

uint64_t elf_load_top(const std::string& elf_path, std::string& err) {
  std::vector<char> buf;
  Elf64_Ehdr eh;
  if (!read_elf64_header(elf_path, buf, eh, err)) return 0;
  // Top of the static image: the highest (p_paddr + p_memsz) over PT_LOAD.
  // p_paddr is the guest-physical placement (== p_vaddr for the identity-mapped
  // bare-metal fixtures), the space the V-scratch GPA also lives in.
  uint64_t top = 0;
  for (uint16_t i = 0; i < eh.e_phnum; ++i) {
    Elf64_Phdr ph;
    const size_t off = static_cast<size_t>(eh.e_phoff) +
                       static_cast<size_t>(i) * eh.e_phentsize;
    if (!load(buf, off, ph)) {
      err = "truncated program header table in '" + elf_path + "'";
      return 0;
    }
    if (ph.p_type != PT_LOAD) continue;
    const uint64_t end = ph.p_paddr + ph.p_memsz;
    if (end > top) top = end;
  }
  return top;  // 0 (empty err) when the ELF has no loadable segments
}

std::string symbolize(const std::string& elf_path, uint64_t addr) {
  std::vector<char> buf;
  Elf64_Ehdr eh;
  std::string ignored;  // symbolize never errors -- empty result is the signal
  if (!read_elf64_header(elf_path, buf, eh, ignored)) return "";

  // Track the highest-valued FUNC symbol whose range covers addr (st_value <=
  // addr < st_value + st_size), falling back to the nearest preceding FUNC
  // when sizes are absent.
  std::string best_name;
  uint64_t best_value = 0;
  bool found = false;

  for (unsigned i = 0; i < eh.e_shnum; ++i) {
    Elf64_Shdr sym_sh;
    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
      break;
    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;

    Elf64_Shdr str_sh;
    if (sym_sh.sh_link >= eh.e_shnum ||
        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
              str_sh))
      continue;

    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
    for (size_t s = 0; s < nsym; ++s) {
      Elf64_Sym sym;
      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
      if (sym.st_shndx == SHN_UNDEF) continue;
      if (ELF64_ST_TYPE(sym.st_info) != STT_FUNC) continue;
      if (sym.st_value > addr) continue;
      // With a size, require coverage; without, accept as a preceding label.
      if (sym.st_size != 0 && addr >= sym.st_value + sym.st_size) continue;
      if (found && sym.st_value <= best_value) continue;

      const size_t noff = str_sh.sh_offset + sym.st_name;
      if (noff >= buf.size()) continue;
      const char* name = buf.data() + noff;
      const size_t avail = buf.size() - noff;
      if (::strnlen(name, avail) == avail) continue;

      best_name = name;
      best_value = sym.st_value;
      found = true;
    }
  }

  if (!found) return "";
  const uint64_t off = addr - best_value;
  if (off == 0) return best_name;
  std::ostringstream ss;
  ss << best_name << "+0x" << std::hex << off;
  return ss.str();
}

}  // namespace andes_sim

// V-register transport staging: the host<->guest-RAM half of the V data
// regfile transfer. The Debug Module abstract-command space has no slots for
// v0..v31 (the RISC-V Debug Spec leaves V to the Program Buffer or
// implementation-specific extensions), so vsim moves v0..v31 by executing a
// vle8.v/vse8.v sweep on the halted hart through the Program Buffer (see
// pb_v_data_sweep in program_buffer.hpp, driven by ResumeDriver on resume and
// StateDrain at drain). That sweep loads/stores the V scratch region of guest
// RAM -- the top page of the mapped span (v_scratch_gpa, L26); this header
// provides the matching host-side copy:
//
//   - stage_v_to_scratch: state.vreg[] -> scratch RAM, called before resume so
//     the ResumeDriver vle8.v sweep reads QEMU 1's V values.
//   - read_v_from_scratch: scratch RAM -> state.vreg[], called after the
//     StateDrain vse8.v sweep so the drained v0..v31 land in state.vreg[]
//     (the handoff file).
//
// The transfer is transparent to the workload: benchmark binaries issue no
// transport code, only the enter_vsim / exit_vsim markers. rt_c_v_regs.c is
// the reference fixture.
//
// Pure logic: no SystemC, no DMI bus. Easy to unit-test.

#pragma once

#include "hybrid/state_abi.h"

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <span>
#include <stdexcept>

namespace hybrid
{

// Total scratch bytes needed: 32 V regs × HYBRID_VLEN_BYTES_MAX. Sized to the
// maximum supported VLEN; the actual per-reg byte count is `vlenb`. Defined in
// the shared ABI (HYBRID_V_SCRATCH_BYTES) so the driver's mmap sizing and this
// consumer agree on one count (L26/F2).
inline constexpr std::size_t kVScratchBytes = HYBRID_V_SCRATCH_BYTES;

// L26: the scratch region is the TOP kVScratchBytes of the mapped RAM span,
// not a fixed address. Scheme D parks it just above the program's declared
// RAM (the driver maps one page more than --mem-size), so no program layout
// can collide with it. This is the single source of truth for the GUEST
// address the Program-Buffer sweep (ResumeDriver/StateDrain) loads/stores
// through; the host stager below copies span-relative and needs no base.
inline constexpr auto v_scratch_gpa(uint64_t ram_base, std::size_t ram_size)
  -> uint64_t
{
  return ram_base + static_cast<uint64_t>(ram_size) - kVScratchBytes;
}

// Sentinel for "no V scratch configured". ResumeDriver/StateDrain default to
// it; a non-V handoff never consults the scratch GPA, so that is fine, but if
// a V handoff reaches the sweep with the GPA still unset the driver throws
// (loud) rather than silently transporting V through a bogus address.
inline constexpr uint64_t kVScratchGpaUnset =
  static_cast<uint64_t>(-1);

namespace detail
{

// Byte offset of the scratch region inside a RAM span: its top page. Throws
// if the span is smaller than one scratch page (a too-small RAM mapping).
inline auto scratch_offset(std::size_t ram_size) -> std::size_t
{
  if (ram_size < kVScratchBytes)
    throw std::runtime_error(
      "v_regfile_xfer: RAM span smaller than the V scratch page");
  return ram_size - kVScratchBytes;
}

}  // namespace detail

// Copy state.vreg[] into the span's top scratch page. Called just before vsim
// resumes the hart so the fixture can vle8.v from scratch and pick up QEMU 1's
// V values.
inline void stage_v_to_scratch(const hybrid_state_v1& state,
                               std::span<uint8_t> ram)
{
  const auto off = detail::scratch_offset(ram.size());
  std::memcpy(ram.data() + off, state.vreg, kVScratchBytes);
}

// Copy the span's top scratch page into state.vreg[]. Called inside the vsim
// drain path after the fixture's prologue vse8.v has settled the (possibly
// mutated) regfile bytes into RAM.
inline void read_v_from_scratch(hybrid_state_v1& state,
                                std::span<const uint8_t> ram)
{
  const auto off = detail::scratch_offset(ram.size());
  std::memcpy(state.vreg, ram.data() + off, kVScratchBytes);
}

}  // namespace hybrid
